function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 10^5 characters.';
  if (!/^[a-z]+$/.test(s)) return 's must contain only lowercase letters.';
  if (!Number.isInteger(k) || k < 0 || k > 25) return 'k is an integer from 0 to 25.';
  return null;
}

