function longestIdealString(s, k) {
  const dp = new Array(26).fill(0);
  for (const ch of s) {
    const letter = ch.charCodeAt(0) - 97;
    const low = Math.max(0, letter - k);
    const high = Math.min(25, letter + k);
    let longest = 0;
    for (let other = low; other <= high; other++) {
      longest = Math.max(longest, dp[other]);
    }
    dp[letter] = longest + 1;
  }
  return Math.max(...dp);
}

