function longestIdealString(s, k) {
  // Classic O(n^2) chain DP over positions: ending[i] is the longest ideal subsequence ending at index i.
  const n = s.length;
  const ending = [];
  let answer = 0;
  for (let i = 0; i < n; i++) {
    ending[i] = 1;
    for (let j = 0; j < i; j++) {
      if (Math.abs(s.charCodeAt(i) - s.charCodeAt(j)) <= k && ending[j] + 1 > ending[i]) ending[i] = ending[j] + 1;
    }
    answer = Math.max(answer, ending[i]);
  }
  return answer;
}

