function generate(rand, size) {
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 12);
  const span = 1 + Math.floor(rand() * 26);
  const start = Math.floor(rand() * (27 - span));
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + start + Math.floor(rand() * span));
  const k = rand() < 0.7 ? Math.floor(rand() * 4) : Math.floor(rand() * 26);
  return [s, k];
}
